class Solution {
public:
    int countCoveredBuildings(int n, vector<vector<int>>& buildings) {
        unordered_map<int, int> minY, maxY, minX, maxX;

        for (auto& b : buildings) {
            int x = b[0], y = b[1];
            if (minY.count(x)) {
                minY[x] = min(minY[x], y);
                maxY[x] = max(maxY[x], y);
            } else {
                minY[x] = maxY[x] = y;
            }
            if (minX.count(y)) {
                minX[y] = min(minX[y], x);
                maxX[y] = max(maxX[y], x);
            } else {
                minX[y] = maxX[y] = x;
            }
        }

        int count = 0;
        for (auto& b : buildings) {
            int x = b[0], y = b[1];
            if (y > minY[x] && y < maxY[x] && x > minX[y] && x < maxX[y]) {
                count++;
            }
        }

        return count;
    }
};
